  // &heart=buna (Eden's call): the neighbours' coffee in place of the bench
  if (new URLSearchParams(location.search).get('heart') === 'buna') root.querySelector('.sc-scene').classList.add('cv--buna');
  if (window.__SC_NOJS) return 'ok';
  /*
 * The little world, both ways round (pointer only; touch taps jump to the product):
 *   hovering an object lifts and warms it and lets its product stand forward in the index;
 *   hovering or focusing a product lifts its object (pure CSS, :has(), so it works without JS).
 * A lifted object keeps its hover while the pointer is anywhere over its resting footprint,
 * so a layer that rises out from under the pointer never makes it flicker.
 */
function sceneWiring(root, SOLID) {
  const scene = root.querySelector('.sc-scene');
  if (!scene) return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const items = {};
  root.querySelectorAll('.sc-item').forEach((li) => { items[li.dataset.slug] = li; });
  const capName = root.querySelector('.sc-cap-name');
  const capKick = root.querySelector('.sc-cap-kicker');
  const capFig = root.querySelector('.sc-cap-fig');
  scene.classList.add('js-scene');
  let active = null;
  let timer = 0;
  const set = (fig) => {
    if (fig === active) return;
    if (active) {
      active.classList.remove('is-open');
      items[active.dataset.slug].classList.remove('is-lit');
    }
    active = fig;
    scene.classList.toggle('has-active', !!fig);
    root.classList.toggle('has-lit', !!fig);
    if (!fig) return;
    fig.classList.add('is-open');
    const li = items[fig.dataset.slug];
    li.classList.add('is-lit');
    capName.textContent = li.querySelector('.sc-name').textContent;
    capKick.textContent = li.querySelector('.sc-kicker').textContent;
    const n = li.querySelector('.sc-fig');
    if (capFig) capFig.textContent = n ? n.textContent : '';
  };
  const inRest = (fig, x, y) => {
    const r = fig.getBoundingClientRect();
    const k = r.width / 240;
    const b = SOLID[fig.dataset.slug];
    return x >= r.left + b[0] * k && x <= r.left + b[2] * k && y >= r.top + b[1] * k && y <= r.top + b[3] * k;
  };
  const figAt = (x, y) => {
    const el = document.elementFromPoint(x, y);
    const fig = el && el.closest ? el.closest('svg.fig') : null;
    return fig && scene.contains(fig) && !fig.classList.contains('is-ghost') ? fig : null;
  };
  scene.addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'mouse') return;
    let fig = figAt(e.clientX, e.clientY);
    if (active && fig !== active && inRest(active, e.clientX, e.clientY) && (!fig || +getComputedStyle(fig).zIndex < +getComputedStyle(active).zIndex)) fig = active;
    clearTimeout(timer);
    if (fig) set(fig);
    else timer = setTimeout(() => set(null), 140);
  });
  scene.addEventListener('pointerleave', () => { clearTimeout(timer); set(null); });
  scene.addEventListener('click', (e) => {
    const fig = figAt(e.clientX, e.clientY) || active;
    if (!fig) return;
    const li = items[fig.dataset.slug];
    li.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
    const h = li.querySelector('.sc-name');
    h.setAttribute('tabindex', '-1');
    h.focus({ preventScroll: true });
  });
}

/*
 * The filter and search (Eden, 2026-10-11): plain words above the list. Choosing one keeps only
 * the matching products in the list and, in the world above, lets the matching objects warm and
 * rise while the others fade to faint ghosts. One filter at a time; All shows everything.
 * The lens opens a quiet field in place of the first line's words and searches every product
 * (names, what they are, their category and their filter words); closing it brings the chosen
 * filter back. Without JS the row stays hidden (it could not work) and every product is listed.
 */
function filterWiring(root) {
  const bar = root.querySelector('.sc-filter');
  if (!bar) return;
  const reduced = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const btns = [...bar.querySelectorAll('.sc-f')];
  const list = root.querySelector('.sc-index');
  const items = [...root.querySelectorAll('.sc-item')];
  const figs = [...root.querySelectorAll('.sc-scene svg.fig')];
  const bySlug = Object.fromEntries(items.map((li) => [li.dataset.slug, li]));
  const countEl = bar.querySelector('.sc-count');
  const sBtn = bar.querySelector('.sc-s-btn');
  const qWrap = bar.querySelector('.sc-qwrap');
  const q = bar.querySelector('.sc-q');
  const line1 = bar.querySelector('.sc-fgroup');
  const has = (el, f) => f === 'all' || (el.dataset.tags || '').split(' ').includes(f);
  const norm = (t) => (t || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  let current = 'all';
  let before = 'all';
  let countTimer = 0;
  let fadeTimer = 0;
  const setCount = (n, later) => {
    clearTimeout(countTimer);
    const say = () => { countEl.textContent = n + ' ' + (n === 1 ? countEl.dataset.one : countEl.dataset.many); };
    if (later) countTimer = setTimeout(say, 300); else say();
  };
  // show the products that pass test(li); the world warms their objects and ghosts the rest
  const show = (test, narrowed, typing) => {
    let n = 0;
    items.forEach((li) => { const on = test(li); li.hidden = !on; if (on) n += 1; });
    figs.forEach((g) => {
      const li = bySlug[g.dataset.slug];
      const on = !!li && !li.hidden;
      g.classList.toggle('is-ghost', narrowed && !on);
      g.classList.toggle('is-picked', narrowed && on);
    });
    root.classList.toggle('is-filtered', narrowed);
    setCount(n, typing);
  };
  const press = (f) => btns.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.f === f)));
  const apply = (f) => { press(f); show((li) => has(li, f), f !== 'all', false); };
  // the list changes calmly: a quick fade out, the change, a gentle fade in (clicks are never held)
  const calmly = (fn) => {
    clearTimeout(fadeTimer);
    if (reduced()) { list.classList.remove('is-fading'); fn(); return; }
    list.classList.add('is-fading');
    fadeTimer = setTimeout(() => { fn(); list.classList.remove('is-fading'); }, 150);
  };
  // the focus ring on the field shows for keyboard users; pointer users see the glow
  document.addEventListener('keydown', (e) => { if (e.key === 'Tab' || e.key === 'Enter' || e.key === ' ') bar.classList.add('kbd'); }, true);
  document.addEventListener('pointerdown', () => bar.classList.remove('kbd'), true);

  const searching = () => bar.classList.contains('is-searching');
  const openSearch = () => {
    if (searching()) { q.focus(); return; }
    before = current;
    line1.style.minHeight = line1.offsetHeight + 'px'; // the row keeps its height, so the list never jumps
    bar.classList.add('is-searching');
    sBtn.setAttribute('aria-expanded', 'true');
    qWrap.hidden = false;
    q.focus();
    // search spans every product: show them all at once (no delayed step that could land after typing)
    clearTimeout(fadeTimer); list.classList.remove('is-fading');
    current = 'all'; apply('all');
  };
  const closeSearch = (focusLens, restore = true) => {
    if (!searching()) return;
    q.value = '';
    qWrap.hidden = true;
    bar.classList.remove('is-searching');
    line1.style.minHeight = '';
    sBtn.setAttribute('aria-expanded', 'false');
    if (restore) { current = before; calmly(() => apply(current)); }
    if (focusLens) sBtn.focus();
  };
  sBtn.addEventListener('click', () => (searching() && !q.value ? closeSearch(true) : openSearch()));
  q.addEventListener('input', () => {
    clearTimeout(fadeTimer); list.classList.remove('is-fading'); // typing always wins
    const term = norm(q.value);
    if (!term) { apply('all'); return; }
    show((li) => norm(li.dataset.q).includes(term), true, true);
  });
  q.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.preventDefault(); closeSearch(true); }
  });
  q.addEventListener('blur', () => { setTimeout(() => { if (!q.value && document.activeElement !== sBtn) closeSearch(false); }, 120); });
  bar.hidden = false;
  bar.addEventListener('click', (e) => {
    const b = e.target.closest('.sc-f');
    if (!b) return;
    if (searching()) closeSearch(false, false);
    if (b.dataset.f === current && !root.classList.contains('is-searching')) { press(current); calmly(() => apply(current)); return; }
    current = b.dataset.f;
    press(current); // the choice shows at once; the list follows calmly
    calmly(() => apply(current));
  });
}

