  filterWiring(root);
  // the painted figures' script (draw-in once on first view; idle only while visible)
  /*
 * Eden Local Apps figures, painted: the forms fade up from the paper the first time each one is
 * seen, then the light warms; idle only while on screen. Without this file (or with reduced motion)
 * every figure is simply fully painted and still: the unpainted start state lives behind .is-armed
 * and the idle loops behind .is-visible, both of which only this script adds.
 */
(() => {
  const figs = document.querySelectorAll("svg.fig");
  if (!figs.length || !("IntersectionObserver" in window)) return;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        e.target.classList.toggle("is-visible", e.isIntersecting);
        if (e.isIntersecting) e.target.classList.add("is-inview");
      }
    },
    { rootMargin: "0px 0px -8% 0px", threshold: 0.2 },
  );
  figs.forEach((f) => {
    f.classList.add("is-armed");
    io.observe(f);
  });
  // the lamp behind the world comes on once, when the world is first seen
  document.querySelectorAll(".pg-lamp").forEach((l) => {
    l.classList.add("is-armed");
    const lo = new IntersectionObserver((es) => {
      if (es.some((e) => e.isIntersecting)) { l.classList.add("is-inview"); lo.disconnect(); }
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.15 });
    lo.observe(l);
  });
})();

  // the commons: the lane lays itself down, the lamp, the walker
  /*
 * The Village Green: the commons comes alive (only with JS, and only without reduced motion).
 * Without this, everything is simply drawn, placed and (at night) lit, and still.
 *   - arrival: the commons is armed, and lays itself down once when the room is first seen;
 *     on phones each part inks in as it comes into view, so the lane's two legs come down together
 *     and close the loop at the foot as you reach the bottom;
 *   - the walker: one small warm light steps round the lane (about 70s a loop), pausing at each
 *     door; the home it calls on does its small stir (.is-stir) while it is there, so at most one
 *     home moves at a time. A home whose neighbour is out (filtered away) is passed by quietly;
 *   - everything pauses while the room is off screen and while the tab is hidden.
 */
function villageWiring(root, WALK) {
  const scene = root.querySelector('.sc-scene');
  if (!scene) return;
  const worlds = [...scene.querySelectorAll('.cv-world')];
  if (!worlds.length || !('IntersectionObserver' in window)) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const figs = {};
  scene.querySelectorAll('svg.fig').forEach((f) => { figs[f.dataset.slug] = f; });
  worlds.forEach((w) => w.classList.add('is-armed'));
  const io = new IntersectionObserver((es) => {
    for (const e of es) {
      e.target.classList.toggle('is-visible', e.isIntersecting);
      if (e.isIntersecting && !e.target.classList.contains('is-inview')) {
        e.target.classList.add('is-inview');
        // once it has all arrived, the arrival is retired: it never plays again (a resize, a
        // layout change), and the end state is exactly the resting drawing
        const w = e.target;
        setTimeout(() => w.classList.add('is-settled'), 3800);
      }
    }
    tick();
  }, { rootMargin: '0px 0px -8% 0px', threshold: 0.12 });
  worlds.forEach((w) => io.observe(w));
  const pio = new IntersectionObserver((es) => {
    for (const e of es) if (e.isIntersecting) { e.target.classList.add('is-in'); pio.unobserve(e.target); }
  }, { rootMargin: '0px 0px -14% 0px', threshold: 0 });
  scene.querySelectorAll('.cv-world--p .cv-io').forEach((g) => pio.observe(g));

  // ---------- the walker
  const phone = window.matchMedia('(max-width: 639px)');
  const PAUSE = 2600, STIR = 3600, START = 3200;
  let i = 0, timer = 0, started = false, last = null;
  const cur = () => (phone.matches ? 'p' : 'd');
  const world = () => scene.querySelector('.cv-world--' + cur());
  const live = () => { const w = world(); return w && w.classList.contains('is-visible') && !document.hidden; };
  // the walker is a small layer of its own (40 scene units square, its middle on the scene's
  // origin), so a step is a move of that layer: 1 scene unit is 2.5% of its own size
  const to = (p) => 'translate(' + Math.round(p[0] * 250) / 100 + '%,' + Math.round(p[1] * 250) / 100 + '%)';
  // the stones are gathered at the doorsteps with bare paper between, so a step takes as long as
  // its stride: short hops along a doorstep, a slow glide between homes
  const place = (w, k, from) => {
    const pts = WALK[cur()].pts, p = pts[k];
    const wk = w.querySelector('.cv-walker');
    if (!wk || !p) return 600;
    let ms = 600;
    if (from != null && pts[from]) {
      ms = Math.round(Math.max(520, Math.min(2200, Math.hypot(p[0] - pts[from][0], p[1] - pts[from][1]) * 24)));
      wk.style.transitionDuration = ms + 'ms, 900ms';
    }
    wk.style.transform = to(p);
    return ms;
  };
  const stir = (slug) => {
    const f = figs[slug];
    if (!f || f.classList.contains('is-ghost') || f.classList.contains('is-open')) return;
    f.classList.add('is-stir');
    setTimeout(() => f.classList.remove('is-stir'), STIR);
  };
  function step() {
    timer = 0;
    if (!live()) return;
    const w = world();
    const data = WALK[cur()];
    if (last !== cur()) { last = cur(); i = 0; place(w, 0); }
    if (!w.classList.contains('is-walking')) { w.classList.add('is-walking'); }
    const prev = i;
    i = (i + 1) % data.pts.length;
    const ms = place(w, i, prev);
    const at = data.stops[i];
    if (at) { setTimeout(() => stir(at), ms * 0.6); timer = setTimeout(step, ms + 60 + PAUSE); }
    else timer = setTimeout(step, ms + 60);
  }
  function tick() {
    if (timer || !live()) return;
    if (!started) {
      started = true;
      worlds.forEach((w) => { const d = WALK[w.classList.contains('cv-world--p') ? 'p' : 'd']; const wk = w.querySelector('.cv-walker'); if (wk && d.pts[0]) wk.style.transform = to(d.pts[0]); });
      timer = setTimeout(step, START);
      return;
    }
    timer = setTimeout(step, 400);
  }
  document.addEventListener('visibilitychange', () => {
    worlds.forEach((w) => w.classList.toggle('is-paused', document.hidden));
    if (document.hidden) { clearTimeout(timer); timer = 0; } else tick();
  });
  phone.addEventListener && phone.addEventListener('change', () => { last = null; });
}

